do_if.value:
$potential_ally_vff == this.ship
                    or not $potential_ally_vff.ishostileto.{$targetstation}
                    or not $potential_ally_vff.owner.hasrelation.enemy.{$targetstation.owner}
                    or not $cl_order_ids.indexof.{@$potential_ally_vff.order.id}

$potential_ally_vff == this.ship
                    or not $potential_ally_vff.ishostileto.{$target_vff}
                    or not $potential_ally_vff.owner.hasrelation.enemy.{$target_vff.owner}
                    or not $cl_order_ids.indexof.{@$potential_ally_vff.order.id}
